func notFoundBack(what string) string {
	switch what {
	case "Cafe", "Feed entry":
		return "/cafes"
	case "Location":
		return "/locations"
	case "Post":
		return "/posts"
	case "Snapshot":
		return "/sources"
	case "User":
		return "/users"
	default:
		return "/"
	}
}

func notFoundBackLabel(what string) string {
	switch what {
	case "Cafe", "Feed entry":
		return "Back to cafes"
	case "Location":
		return "Back to locations"
	case "Post":
		return "Back to posts"
	case "Snapshot":
		return "Back to sources"
	case "User":
		return "Back to users"
	default:
		return "Admin home"
	}
}

